/*
 * NETWORK_$PROCESS_PAGING_REQUEST - Serve one request from the paging socket
 *
 * Original address: 0x00E10628 (no map symbol; inside "I E0F120 NETWORK
 * size = 2DD0")
 * Size: 3842 bytes of code (0x00E10628 .. 0x00E11547, less the 30-byte
 * jump table at 0x00E1077E)
 * Generated by: Claude Opus 5.5 (reviewed by Claude Fable 5.1)
 *
 * A procedure nested in NETWORK_$PAGE_SERVER: its only caller (0x00E11708)
 * runs it when socket 1 has a packet, and it reaches the server's frame
 * through the static link (`movea.l (A6),A2` at 0x00E10630), so the C takes
 * the frame, network_$ps_frame_t.  Replies go out through the server's
 * other nested procedure, the reply sender at 0x00E10510
 * (`movea.l A2,A1 / bsr.w`), network_$ps_send_reply here.
 *
 * Frame (link.w A6,-0x108; D2-D4/A2-A4 saved), locals:
 *   (-0x10) addr[2]    {routing key, destination node} for the packet size
 *   (-0x30) req        copy of the request's 32-byte object/page record
 *   (-0xC0) attrs      AST_$GET_ATTRIBUTES output (page-in)
 *   (-0xC4) rcv_st     APP_$RECEIVE status
 *   (-0xCC) st         the working status
 *   (-0xD4) new_ppn, (-0xD8) st2
 *   (-0xE0) netlog_word  longword whose two words are NETLOG_$LOG_IT's
 *                      arguments 5 and 6: top byte the log kind (1..4),
 *                      bits 23..20 the socket queue depth, low 20 bits the
 *                      requesting node
 *   (-0xE6) attr_flags, (-0xE8) touch_flags, (-0xEA) touch_count  words
 *   (-0x106) old_flag  VTOCE_$NEW_TO_OLD's flag byte
 *   A3 the ASTE, D2w packets per page, D3b "object is anonymous".
 *
 * Blocks:
 *   0x00E10632-0x00E10660  receive; any status (the queue-empty status
 *                          0x110006 is tested first) ends the call
 *   0x00E10662-0x00E10740  save the data pages, start clock, arrival clock,
 *                          netlog word, reply addressing, copy the request
 *                          (at most 0x32 bytes) and return its header
 *   0x00E10742-0x00E10768  NETWORK_$PAGING_BACKLOG[min(queue depth, 8)]++
 *   0x00E10768-0x00E1077A  dispatch on the request type through the table at
 *                          0x00E1077E (0a90 0d7a 0d7a 0d7a 055c 0d7a 0b7e
 *                          0d7a 0d7a 0d7a 0952 0d7a 001e 0d7a 0ac8); types
 *                          >= 15 and the 0d7a slots go to 0x00E114F8
 *   0x00E1079C-0x00E10CD6  0xC page-in: touch the pages, send them one
 *                          packet at a time, reply 0xD, log kind 1
 *   0x00E10CDA-0x00E110CC  4 page-out: checksum, associate or copy the
 *                          page, set the DTM, reply 5, log kind 2
 *   0x00E110D0-0x00E1120A  0xA set attribute: reply 0xB, log kind 3
 *   0x00E1120E-0x00E11242  0 echo: reply 1 is the request itself
 *   0x00E11246-0x00E112F8  0xE ring information: reply 0xF
 *   0x00E112FC-0x00E114E8  6 attributes: reply 7, log kind 4
 *   0x00E114EC-0x00E114F6  the NETLOG_$LOG_IT(0x14, eight args) tail shared by
 *                          the four logs
 *   0x00E114F8-0x00E1153A  unknown type: reply 9 with
 *                          status_$network_unknown_request_type
 *
 * Quirks reproduced:
 *   - The page-in send loops stop on the local status (A6-0xCC), not on the
 *     send status in the frame; for a "page null" reply that status is
 *     0x50008 itself, so only the first zero page is sent (0x00E10B32).  An
 *     attribute error after the pages were touched is likewise sent once.
 *   - M$DIU$LLW(0, data_len) is subtracted from the packet count (0x00E10A76);
 *     it is always 0.
 *   - A page-out checksum mismatch calls CRASH_SYSTEM with the bad-checksum
 *     cell 0x00E10268 and carries on as if it returned (0x00E10D16).
 *   - network_$page_chksum is pushed &data_len as a second argument it never
 *     reads (0x00E10B1A, 0x00E10CFE).
 *   - AREA_$TOUCH returns holding ML lock 0x14 (only ML_$UNLOCK follows).
 *   - The attribute reply's logging is not conditioned on its status.
 *   - The log's elapsed times are `divs.w #0xfa` of the low 32 clock bits;
 *     a quotient that does not fit 16 bits leaves the dividend in the image
 *     (V set), where C truncates the quotient.
 */

#include "network/network_internal.h"
#include "app/app.h"
#include "area/area.h"
#include "ast/ast.h"
#include "anon/anon.h"
#include "math/math.h"
#include "ml/ml.h"
#include "mmap/mmap.h"
#include "netbuf/netbuf.h"
#include "netlog/netlog.h"
#include "os/os.h"
#include "pkt/pkt.h"
#include "proc1/proc1.h"
#include "ring/ring.h"
#include "time/time.h"
#include "vtoc/vtoc.h"
#include "wp/wp.h"
#include "misc/crash_system.h"

/* Request types (the jump table at 0x00E1077E) and their replies */
#define NETWORK_PS_RQST_ECHO        0x0
#define NETWORK_PS_RQST_PAGOUT      0x4
#define NETWORK_PS_RQST_GETATTR     0x6
#define NETWORK_PS_RQST_SETATTR     0xA
#define NETWORK_PS_RQST_PAGIN       0xC
#define NETWORK_PS_RQST_RING_INFO   0xE
#define NETWORK_PS_RQST_TYPES       0xF         /* `cmpi.w #0xf` 0x00E1076C */
#define NETWORK_PS_REPLY_UNKNOWN    0x9

/* The paging socket, whose queue depth picks the backlog bucket */
#define NETWORK_PS_SOCK_PAGING      1
#define NETWORK_PS_BACKLOG_LAST     8           /* `cmpi.w #0x8` 0x00E1074E */

/* Longest request copied: `moveq #0x32,D0` 0x00E10700 */
#define NETWORK_PS_RQST_MAX         0x32
/* The page-in request without the count word: `cmpi.w #0x28` 0x00E10818 */
#define NETWORK_PS_PAGIN_OLD_LEN    0x28

/* The reply version most replies carry, and the page-in version cap */
#define NETWORK_PS_VERSION          8

/* ML lock of the physical page map */
#define NETWORK_PS_PMAP_LOCK        0x14

/* NETLOG_$LOG_IT kind for the page server: `move.w #0x14,-(SP)` 0x00E114EC */
#define NETWORK_PS_NETLOG_KIND      0x14

/* Service bit 1 of NETWORK_$ALLOWED_SERVICE byte 1: `btst.b #0x1,(0x343,A5)` */
#define NETWORK_PS_SERVICE_BIT      NETWORK_SERVICE_FILE_CAPABLE

/* pkt_flags bit 2 (`btst.l #0x2`) refuses the request */
#define NETWORK_PS_FLAG_REFUSE      0x0004

/* ANON objects: the area id is the low word of uid.low */
#define NETWORK_PS_SEG_SHIFT        5
#define NETWORK_PS_PAGE_MASK        0x1F

/* The 48-bit clock's low 32 bits, i.e. the longword at clock+2. */
static uint32_t network_$ppr_clock_low32(const clock_t *c)
{
    return (uint32_t)((c->high << 16) | c->low);
}

/*
 * 0x00E114A4-0x00E114F6 and its three twins: stamp end_clock is done by the
 * caller; this sets the kind byte and pushes the eight arguments.
 */
static void network_$ppr_log(network_$ps_frame_t *ps, uint32_t *netlog_word,
                             uint8_t kind, uid_t *uid, uint16_t seg,
                             uint16_t page)
{
    int16_t queue_ms, serve_ms;

    *netlog_word = (*netlog_word & 0x00FFFFFFu) | ((uint32_t)kind << 24);
    serve_ms = (int16_t)((int32_t)(network_$ppr_clock_low32(&ps->end_clock) -
                                   network_$ppr_clock_low32(&ps->start_clock)) /
                         250);
    queue_ms = (int16_t)((int32_t)(network_$ppr_clock_low32(&ps->start_clock) -
                                   network_$ppr_clock_low32(&ps->arrival)) /
                         250);
    NETLOG_$LOG_IT(NETWORK_PS_NETLOG_KIND, (uint32_t *)uid, seg, page,
                   (uint16_t)(*netlog_word >> 16), (uint16_t)*netlog_word,
                   (uint16_t)queue_ms, (uint16_t)serve_ms);
}

/* 0x00E114F8-0x00E11510 and the other "dump what came with it" sites */
static void network_$ppr_dump(network_$ps_frame_t *ps)
{
    if (ps->data_pages[0] != 0) {
        PKT_$DUMP_DATA(ps->data_pages, ps->data_len);
    }
}

/* The image's longword block copies (move.l (A0)+,(A1)+), byte by byte. */
static void network_$ppr_copy(void *dst, const void *src, int16_t len)
{
    uint8_t *d = (uint8_t *)dst;
    const uint8_t *s = (const uint8_t *)src;

    while (len-- > 0) {
        *d++ = *s++;
    }
}

void NETWORK_$PROCESS_PAGING_REQUEST(network_$ps_frame_t *ps)
{
    network_$ps_rqst_t *rq = &ps->rqst;
    network_$ps_reply_t *rp = &ps->reply;
    network_$rcv_rec_t *rcv;
    uint32_t addr[2];                   /* (-0x10,A6) */
    network_$page_request_t req;        /* (-0x30,A6) */
    network_$ps_attrs_t attrs;          /* (-0xC0,A6) */
    status_$t rcv_st;                   /* (-0xC4,A6) */
    status_$t st;                       /* (-0xCC,A6) */
    uint32_t new_ppn;                   /* (-0xD4,A6) */
    status_$t st2;                      /* (-0xD8,A6) */
    uint32_t netlog_word;               /* (-0xE0,A6) */
    uint16_t attr_flags;                /* (-0xE6,A6) */
    uint16_t touch_flags;               /* (-0xE8,A6) */
    int16_t touch_count;                /* (-0xEA,A6) */
    int8_t old_flag;                    /* (-0x106,A6) */
    aste_t *aste;                       /* A3 */
    uint16_t ppp;                       /* D2w: packets per page */
    int8_t anon;                        /* D3b */
    uint16_t depth;
    int32_t pkts, limit;                /* D4, D0 */
    int16_t seq, n, k, i;
    uint32_t oldbits;

    /* 0x00E10632-0x00E10660 */
    ps->data_pages[0] = 0;
    APP_$RECEIVE(NETWORK_PS_SOCK_PAGING, &ps->rec, &rcv_st);
    if (rcv_st == status_$network_buffer_queue_is_empty || rcv_st != status_$ok) {
        return;
    }

    /* 0x00E10662-0x00E10690 */
    for (i = 0; i < 4; i++) {
        ps->data_pages[i] = ps->rec.data_pages[i];
    }
    if (NETLOG_$OK_TO_LOG_SERVER < 0) {
        TIME_$ABS_CLOCK(&ps->start_clock);
    }
    ps->arrival.high = ps->rec.src_addr;
    ps->arrival.low = ps->rec.src_port;

    /* 0x00E10692-0x00E106BE: the image never initialises A6-0xE0; every
     * bit a log reads is stored first (top byte at the log site). */
    netlog_word = 0;
    depth = (uint16_t)((((uint32_t)ps->rec.flags_hi << 16 | ps->rec.flags_lo) &
                        0x7F8000u) >> 15);
    netlog_word = (netlog_word & 0xFF0FFFFFu) |
                  ((uint32_t)(uint8_t)(depth << 4) << 16);
    netlog_word &= 0xFFF00000u;
    rcv = (network_$rcv_rec_t *)ARCH_VA_TO_PTR(ps->rec.reply);
    netlog_word |= rcv->node_b;

    /* 0x00E106C0-0x00E1070C */
    ps->src_node_or = ps->rec.hdr_f06;
    ps->routing_key = ps->rec.hdr_f12;
    ps->data_len = rcv->data_len;
    ps->src_node = rcv->node_a;
    ps->src_sock = rcv->sock_a;
    ps->dest_node = rcv->node_b;
    ps->dest_sock = rcv->sock_b;
    ps->pkt_flags = (uint16_t)rcv->flags;
    ps->request_id = rcv->request_id;
    ps->rqst_copy_len = NETWORK_PS_RQST_MAX;
    if (!(NETWORK_PS_RQST_MAX <= rcv->rqst_len)) {
        ps->rqst_copy_len = rcv->rqst_len;
    }

    /* 0x00E10710-0x00E10740 */
    OS_$DATA_COPY(ARCH_VA_TO_PTR(ps->rec.data), rq->bytes,
                  (uint32_t)ps->rqst_copy_len);
    ps->rtn_hdr_va = ps->rec.data & 0xFFFFFC00u;       /* andi.w #-0x400 */
    NETBUF_$RTN_HDR(&ps->rtn_hdr_va);

    /* 0x00E10742-0x00E10768 */
    depth = SOCK_$DATA.socket_ptr[NETWORK_PS_SOCK_PAGING]->queue_count;
    if (depth <= NETWORK_PS_BACKLOG_LAST) {
        NETWORK_$PAGING_BACKLOG[depth]++;
    } else {
        NETWORK_$PAGING_BACKLOG[NETWORK_PS_BACKLOG_LAST]++;
    }

    /* 0x00E10768-0x00E1077A */
    if ((uint16_t)rq->type >= NETWORK_PS_RQST_TYPES) {
        goto unknown;
    }
    switch (rq->type) {
    case NETWORK_PS_RQST_PAGIN:
        goto pagin;
    case NETWORK_PS_RQST_PAGOUT:
        goto pagout;
    case NETWORK_PS_RQST_SETATTR:
        goto setattr;
    case NETWORK_PS_RQST_ECHO:
        goto echo;
    case NETWORK_PS_RQST_RING_INFO:
        goto ring_info;
    case NETWORK_PS_RQST_GETATTR:
        goto getattr;
    default:
        goto unknown;
    }

pagin:
    /* 0x00E1079C-0x00E107B6 */
    ps->touched = 0;
    network_$ppr_dump(ps);

    /* 0x00E107B8-0x00E10800: the packet size */
    ps->data_len = 0x400;
    if (rq->pagin.version >= NETWORK_PS_VERSION) {
        k = (int16_t)rq->pagin.page_size;
        if (k < 0x400) {
            k = 0x400;
        }
        ps->data_len = k;
    }
    addr[1] = ps->dest_node;
    addr[0] = ps->routing_key;
    ps->data_len = (int16_t)NETWORK_$GET_PKT_SIZE(addr, (uint16_t)ps->data_len);
    ppp = (uint16_t)(0x400u / (uint16_t)ps->data_len);  /* divu.w: D2w */

    /* 0x00E10802-0x00E10814 */
    if ((NETWORK_$ALLOWED_SERVICE & NETWORK_PS_SERVICE_BIT) == 0 ||
        (ps->pkt_flags & NETWORK_PS_FLAG_REFUSE) != 0) {
        rp->hdr.status = status_$network_request_denied_by_remote_node;
        goto pagin_reply;                                /* 0x00E10A06 */
    }

    /* 0x00E10818-0x00E10870 */
    if (ps->rqst_copy_len == NETWORK_PS_PAGIN_OLD_LEN) {
        if (rq->pagin.limit < 8) {
            touch_count = rq->pagin.limit;
        } else {
            touch_count = 0x20;
        }
    } else {
        touch_count = (int16_t)rq->pagin.count;
    }
    touch_flags = 2;
    if (rq->pagin.flag_1a < 0) {
        touch_flags = 3;
    }
    req = rq->pagin.req;
    anon = (req.uid.high == ANON_$UID.high) ? (int8_t)0xFF : 0;

    if (anon < 0) {
        /* 0x00E10872-0x00E108C2 */
        AREA_$TOUCH((area_$handle_t *)&req.uid.low,
                    (uint16_t)(req.page_num >> NETWORK_PS_SEG_SHIFT),
                    (uint16_t)(req.page_num & NETWORK_PS_PAGE_MASK), 0,
                    ps->ppns, &st);
        if (st == status_$ok) {
            ps->touched = 1;
            MMAP_$WIRE(ps->ppns[0]);
        }
        ML_$UNLOCK(NETWORK_PS_PMAP_LOCK);
        goto pagin_status;                               /* 0x00E109FE */
    }

    /* 0x00E108C6-0x00E108F4 */
    aste = AST_$ACTIVATE_AND_WIRE(&req.uid,
                                  (uint16_t)(req.page_num >> NETWORK_PS_SEG_SHIFT),
                                  &st);
    if (aste == NULL) {
        goto pagin_status;
    }
    if (aste->aote->remote_flag < 0) {
        st = status_$file_object_not_found;
        goto pagin_unwire_aste;                          /* 0x00E109FA */
    }

    /* 0x00E10902-0x00E1097A */
    ML_$LOCK(NETWORK_PS_PMAP_LOCK);
    ps->touched = (int16_t)AST_$TOUCH(aste, ps->dest_node,
                                      (uint16_t)(req.page_num & NETWORK_PS_PAGE_MASK),
                                      (uint16_t)touch_count, ps->ppns, &st,
                                      touch_flags);
    if (ps->touched > 0 && st == status_$ok && ps->touched != 0) {
        n = (int16_t)(ps->touched - 1);
        k = 0;
        do {
            MMAP_$WIRE(ps->ppns[k]);
            k++;
        } while (--n != -1);
    }
    ML_$UNLOCK(NETWORK_PS_PMAP_LOCK);

    /* 0x00E1097C-0x00E109F4: the object's attributes and clocks */
    if (ps->touched > 0) {
        file_$obj_loc_t *loc = (file_$obj_loc_t *)(void *)&rp->bytes[8];

        loc->uid.high = req.uid.high;
        loc->uid.low = req.uid.low;
        loc->flags &= (int8_t)~FILE_OBJ_LOC_SCRATCH;     /* bclr #6,(-0x1c3) */
        if (rq->pagin.flag_18 < 0 && rq->pagin.version >= 7) {
            attr_flags = 0x280;
        } else {
            attr_flags = 0x80;
        }
        AST_$GET_ATTRIBUTES(loc, attr_flags, &attrs, &st2);
        if (st2 != status_$ok) {
            st = st2;
        }
        rp->pagin.dtm_high = attrs.dtm.high;
        rp->pagin.dtm_low = attrs.dtm.low;
        rp->pagin.clock_high = attrs.clock.high;
        rp->pagin.clock_low = attrs.clock.low;
        rp->pagin.acl_high = attrs.acl.high;
        rp->pagin.acl_low = attrs.acl.low;
    }

pagin_unwire_aste:
    aste->wire_count--;                                  /* 0x00E109FA */

pagin_status:
    rp->hdr.status = st;                                 /* 0x00E109FE */

pagin_reply:
    /* 0x00E10A0E-0x00E10A6A */
    rp->pagin.req = rq->pagin.req;
    rp->pagin.req.reserved[0] = 0;                       /* (-0x1d0): +0x18 */
    rp->pagin.req.reserved[3] &= 0xFFFF0000u;            /* clr.w (-0x1c2): +0x26 */
    rp->type = NETWORK_PS_RQST_PAGIN + 1;
    if (rq->pagin.version >= NETWORK_PS_VERSION) {
        rp->pagin.version = NETWORK_PS_VERSION;
    } else {
        rp->pagin.version = rq->pagin.version;
    }
    rp->pagin.more = 0;
    rp->pagin.seq = 1;
    rp->pagin.chksum = 0;
    ps->reply_len = 0x4A;
    ps->pkt_flags = 0x20;
    if (ps->touched == 0) {
        ps->data_pages[0] = 0;
        ps->data_len = 0;
        goto send;                                       /* 0x00E11538 */
    }

    /* 0x00E10A6E-0x00E10ABE: packets to send */
    pkts = (int32_t)(int16_t)ppp * ps->touched -
           (int32_t)(uint32_t)M$DIU$LLW(0, (uint16_t)ps->data_len);
    limit = (int32_t)M$DIS$LLL((long)((int32_t)(int16_t)rq->pagin.count << 10),
                               (long)(uint16_t)ps->data_len);
    if (pkts > limit) {
        pkts = limit;
    }
    if ((int16_t)pkts > rq->pagin.limit) {
        rp->pagin.page_cnt = rq->pagin.limit;
    } else {
        rp->pagin.page_cnt = (int16_t)pkts;
        rp->pagin.more = (int16_t)(rp->pagin.more | 0x8000);  /* bset #7 */
    }

    if (rp->hdr.status == status_$pmap_page_null) {
        /* 0x00E10ACC-0x00E10B40: zero pages */
        k = ps->touched;
        if (k > (int16_t)rq->pagin.count) {
            k = (int16_t)rq->pagin.count;
        }
        rp->pagin.page_cnt = k;
        if (rp->pagin.version > 1) {
            ps->data_pages[0] = 0;
            ps->data_len = 0;
            network_$ps_send_reply(ps);
        } else if (rp->pagin.page_cnt != 0) {
            n = (int16_t)(rp->pagin.page_cnt - 1);
            seq = 1;
            do {
                ps->data_pages[0] = NETWORK_$ZERO_PAGE_PA;
                rp->pagin.seq = seq;
                if (NETWORK_$DO_CHKSUM < 0) {
                    rp->pagin.chksum = network_$page_chksum(ps->data_pages);
                }
                network_$ps_send_reply(ps);
                if (st != status_$ok) {
                    break;
                }
                seq++;
            } while (--n != -1);
        }
        goto pagin_count;                                /* 0x00E10C54 */
    }

    if ((int16_t)ppp > 1) {
        /* 0x00E10B4A-0x00E10BC2: several packets per page */
        ps->data_pages[0] = ps->ppns[0] << 10;
        if (rp->pagin.page_cnt != 0) {
            n = (int16_t)(rp->pagin.page_cnt - 1);
            seq = 1;
            k = 0;
            do {
                rp->pagin.seq = seq;
                if (NETWORK_$DO_CHKSUM < 0) {
                    rp->pagin.chksum = network_$page_chksum(ps->data_pages);
                }
                network_$ps_send_reply(ps);
                if (st != status_$ok) {
                    break;
                }
                ps->data_pages[0] += (uint16_t)ps->data_len;
                if ((ps->data_pages[0] & 0x3FF) == 0) {
                    k++;
                    ps->data_pages[0] = ps->ppns[k] << 10;
                }
                seq++;
            } while (--n != -1);
        }
    } else if (rp->pagin.page_cnt != 0) {
        /* 0x00E10BC4-0x00E10C10: a page per packet */
        n = (int16_t)(rp->pagin.page_cnt - 1);
        seq = 1;
        k = 0;
        do {
            ps->data_pages[0] = ps->ppns[k] << 10;
            rp->pagin.seq = seq;
            if (NETWORK_$DO_CHKSUM < 0) {
                rp->pagin.chksum = network_$page_chksum(ps->data_pages);
            }
            network_$ps_send_reply(ps);
            if (st != status_$ok) {
                break;
            }
            seq++;
            k++;
        } while (--n != -1);
    }

    /* 0x00E10C14-0x00E10C52 */
    ML_$LOCK(NETWORK_PS_PMAP_LOCK);
    if (ps->touched != 0) {
        n = (int16_t)(ps->touched - 1);
        k = 0;
        do {
            MMAP_$UNWIRE(ps->ppns[k]);
            k++;
        } while (--n != -1);
    }
    ML_$UNLOCK(NETWORK_PS_PMAP_LOCK);

pagin_count:
    /* 0x00E10C54-0x00E10CD6 */
    NETWORK_$MULT_PAGIN_RQST_CNT += (uint16_t)rp->pagin.page_cnt;
    PROC1_$DATA.stats[PROC1_$CURRENT].stat[3] += (uint32_t)(int32_t)rp->pagin.page_cnt;
    if (NETLOG_$OK_TO_LOG_SERVER >= 0) {
        return;
    }
    TIME_$ABS_CLOCK(&ps->end_clock);
    ps->log_seg = (uint16_t)(rq->pagin.req.page_num >> NETWORK_PS_SEG_SHIFT);
    ps->log_page = (uint16_t)(rq->pagin.req.page_num & NETWORK_PS_PAGE_MASK);
    network_$ppr_log(ps, &netlog_word, 1, (uid_t *)(void *)&rq->bytes[6], ps->log_seg,
                     ps->log_page);
    return;

pagout:
    /* 0x00E10CDA-0x00E10CEE */
    NETWORK_$PAGOUT_RQST_CNT++;
    if ((ps->pkt_flags & NETWORK_PS_FLAG_REFUSE) != 0) {
        goto dump;                                       /* 0x00E112E0 */
    }
    if (ps->data_pages[0] == 0) {
        return;
    }

    /* 0x00E10CF2-0x00E10D36: a page whose checksum is wrong */
    if (NETWORK_$DO_CHKSUM < 0 && rq->pagout.chksum != 0 &&
        network_$page_chksum(ps->data_pages) != rq->pagout.chksum) {
        CRASH_SYSTEM(&network_$read_ahead_chksum_status);
        PKT_$DUMP_DATA(ps->data_pages, ps->data_len);
        NETWORK_$BAD_CHKSUM_CNT++;
        return;
    }

    /* 0x00E10D3A-0x00E10D76 */
    touch_flags = 0;
    if (rq->pagout.flag < 0) {
        touch_flags = 1;
    }
    if (MMAPE_FOR_VPN(ps->data_pages[0] >> 10)->wire_count != 0) {
        MMAPE_FOR_VPN(ps->data_pages[0] >> 10)->wire_count = 0;
        NETWORK_$CLEAR_WIRED++;
    }

    /* 0x00E10D7A-0x00E10D96 */
    req = rq->pagout.req;
    anon = (req.uid.high == ANON_$UID.high) ? (int8_t)0xFF : 0;

    if (ps->data_len == 0x400) {
        /* 0x00E10DA2-0x00E10E42: a whole page is given to the object */
        if (anon < 0) {
            AREA_$ASSOC((int16_t)req.uid.low,
                        (uint16_t)(req.page_num >> NETWORK_PS_SEG_SHIFT),
                        (int16_t)(req.page_num & NETWORK_PS_PAGE_MASK),
                        ps->data_pages[0] >> 10, &st);
        } else {
            AST_$ASSOC(&req.uid, (uint16_t)(req.page_num >> NETWORK_PS_SEG_SHIFT),
                       ps->dest_node,
                       (uint16_t)(req.page_num & NETWORK_PS_PAGE_MASK),
                       touch_flags, ps->data_pages[0] >> 10, &st);
        }
        if (st != status_$ok) {
            NETBUF_$RTN_DAT(ps->data_pages[0]);          /* 0x00E10F8C */
        } else {
            /* and NETBUF gets a fresh page in exchange (0x00E10E14) */
            WP_$CALLOC(&new_ppn, &st2);
            if (st2 != status_$ok) {
                CRASH_SYSTEM(&st2);
            }
            NETBUF_$RTN_DAT(new_ppn << 10);
        }
        goto pagout_reply;
    }

    /* 0x00E10E46-0x00E10F3A: a partial page is copied into the object */
    if (anon < 0) {
        AREA_$TOUCH((area_$handle_t *)&req.uid.low,
                    (uint16_t)(req.page_num >> NETWORK_PS_SEG_SHIFT),
                    (uint16_t)(req.page_num & NETWORK_PS_PAGE_MASK), 0,
                    ps->ppns, &st);
        if (st == status_$ok) {
            ps->touched = 1;
            MMAP_$WIRE(ps->ppns[0]);
        }
        ML_$UNLOCK(NETWORK_PS_PMAP_LOCK);
    } else {
        aste = AST_$ACTIVATE_AND_WIRE(&req.uid,
                                      (uint16_t)(req.page_num >> NETWORK_PS_SEG_SHIFT),
                                      &st);
        if (aste != NULL) {
            if (aste->aote->remote_flag < 0) {
                st = status_$file_object_not_found;
            } else {
                ML_$LOCK(NETWORK_PS_PMAP_LOCK);
                ps->touched = (int16_t)AST_$TOUCH(aste, ps->dest_node,
                                                  (uint16_t)(req.page_num & NETWORK_PS_PAGE_MASK),
                                                  1, ps->ppns, &st, touch_flags);
                if (ps->touched > 0 && st == status_$ok) {
                    MMAP_$WIRE(ps->ppns[0]);
                }
                ML_$UNLOCK(NETWORK_PS_PMAP_LOCK);
            }
            aste->wire_count--;                          /* 0x00E10F38 */
        }
    }

    /* 0x00E10F3C-0x00E10F96 */
    if (st == status_$ok) {
        ps->copy_dst_pa = ps->ppns[0] << 10;
        ps->copy_src_pa = ps->data_pages[0];
        network_$phys_copy(ps->copy_dst_pa, ps->copy_src_pa, ps->data_len);
        MMAPE_FOR_VPN(ps->ppns[0])->flags2 |= MMAPE_FLAG2_MODIFIED;  /* bset #6 */
        WP_$UNWIRE(ps->ppns[0]);
    }
    NETBUF_$RTN_DAT(ps->data_pages[0]);

pagout_reply:
    /* 0x00E10F98-0x00E10FFC */
    ps->data_pages[0] = 0;
    ps->data_len = 0;
    rp->hdr.status = st;
    rp->type = NETWORK_PS_RQST_PAGOUT + 1;
    rp->pagout.u.req = rq->pagout.req;
    TIME_$ABS_CLOCK(&ps->deadline);
    TIME_$CLOCK((clock_t *)(void *)&rp->bytes[0x2E]);
    if (rp->hdr.status == status_$ok && anon >= 0) {
        AST_$SET_DTS(0x27, &req.uid, (uint32_t *)&ps->deadline,
                     (uint32_t *)(void *)&rp->bytes[0x2E], &st);
    }

    /* 0x00E10FFE-0x00E11048 */
    rp->pagout.u.f.dtm_high = ps->deadline.high;
    ps->reply_len = 0x34;
    rp->pagout.u.f.dtm_bits = 0;
    if (rq->pagout.version >= 4) {
        rp->pagout.dtm_low = ps->deadline.low;
    } else {
        rp->pagout.u.f.dtm_bits = (uint8_t)((ps->deadline.low >> 8) & 0xF8);
        ps->reply_len = 0x2C;
    }
    rp->pagout.u.f.zero_1c = 0;
    rp->pagout.u.f.zero_20 = 0;
    rp->pagout.version = NETWORK_PS_VERSION;
    ps->pkt_flags = 8;
    network_$ps_send_reply(ps);

    /* 0x00E1104C-0x00E110CC */
    if (rp->hdr.status == status_$ok && st == status_$ok) {
        PROC1_$DATA.stats[PROC1_$CURRENT].stat[3]++;
    }
    if (NETLOG_$OK_TO_LOG_SERVER >= 0) {
        return;
    }
    TIME_$ABS_CLOCK(&ps->end_clock);
    ps->log_seg = (uint16_t)(req.page_num >> NETWORK_PS_SEG_SHIFT);
    ps->log_page = (uint16_t)(req.page_num & NETWORK_PS_PAGE_MASK);
    network_$ppr_log(ps, &netlog_word, 2, &req.uid, ps->log_seg, ps->log_page);
    return;

setattr:
    /* 0x00E110D0-0x00E1114C */
    NETWORK_$ATTRIB_RQST_CNT++;
    network_$ppr_dump(ps);
    if ((ps->pkt_flags & NETWORK_PS_FLAG_REFUSE) != 0) {
        return;
    }
    AST_$SET_ATTRIBUTE((uid_t *)(void *)&rq->bytes[4], (uint16_t)rq->setattr.attr_id,
                       &rq->bytes[0x0E], &st);
    rp->hdr.status = st;
    rp->type = NETWORK_PS_RQST_SETATTR + 1;
    TIME_$ABS_CLOCK(&ps->deadline);
    if (rp->hdr.status == status_$ok) {
        AST_$SET_DTS(0x23, (uid_t *)(void *)&rq->bytes[4],
                     (uint32_t *)&ps->deadline, (uint32_t *)&ps->deadline, &st);
    }

    /* 0x00E11150-0x00E111B0 */
    rp->setattr.dtm_high = ps->deadline.high;
    rp->setattr.dtm_low = ps->deadline.low;
    if (rq->setattr.version <= 4) {
        rp->setattr.dtm_low = (uint16_t)((rp->setattr.dtm_low >> 8) & 0xF8);
    }
    rp->setattr.version = NETWORK_PS_VERSION;
    ps->reply_len = 0x0E;
    ps->data_pages[0] = 0;
    ps->data_len = 0;
    ps->pkt_flags = 8;
    if ((uint32_t)(uint16_t)NETWORK_$SERVICE_TIME + ps->arrival.high <
        ps->deadline.high) {
        NETWORK_$2LONG1++;
        st = status_$network_remote_node_failed_to_respond;
    } else {
        network_$ps_send_reply(ps);
    }

    /* 0x00E111B2-0x00E1120A */
    if (NETLOG_$OK_TO_LOG_SERVER >= 0 || rp->hdr.status != status_$ok ||
        st != status_$ok) {
        return;
    }
    TIME_$ABS_CLOCK(&ps->end_clock);
    network_$ppr_log(ps, &netlog_word, 3, (uid_t *)(void *)&rq->bytes[4], 0, 0);
    return;

echo:
    /* 0x00E1120E-0x00E11242 */
    OS_$DATA_COPY(rq->bytes, rp->bytes, (uint32_t)ps->rqst_copy_len);
    rp->type = NETWORK_PS_RQST_ECHO + 1;
    ps->reply_len = (int16_t)ps->rqst_copy_len;
    ps->pkt_flags = (uint16_t)((ps->pkt_flags & ~0x0010) | 0x0020);
    goto send_dump;

ring_info:
    /* 0x00E11246-0x00E112D4 */
    NETWORK_$INFO_RQST_CNT++;
    rp->hdr.status = status_$ok;
    rp->type = NETWORK_PS_RQST_RING_INFO + 1;
    network_$ppr_copy(&rp->bytes[6 + 0x44], &NETWORK_$FAILURE_REC, 0x10);
    network_$ppr_copy(&rp->bytes[6 + 0x08], &RING_$WIRED_DATA.stats[0], 0x3C);
    network_$ppr_copy(&rp->bytes[6 + 0x54], &RING_$WIRED_DATA.swdiag, 0x1E);
    rp->ring.info.swdiag.rcvcnt = RING_$WIRED_DATA.swdiag_rcvcnt;
    rp->ring.info.swdiag.nodeid = RING_$WIRED_DATA.swdiag_nodeid;
    rp->ring.info.xmit_biphase = RING_$WIRED_DATA.xmit_biphase;
    rp->ring.info.rcv_biphase = RING_$WIRED_DATA.rcv_biphase;
    rp->ring.info.xmit_esb = RING_$WIRED_DATA.xmit_esb;
    rp->ring.info.rcv_esb = RING_$WIRED_DATA.rcv_esb;
    rp->ring.info._unknown_00 = 3;
    rp->ring.info.diskless = NETWORK_$DISKLESS;
    rp->ring.info.mother_node = NETWORK_$MOTHER_NODE;
    ps->pkt_flags = 0x20;
    ps->reply_len = 0x80;

send_dump:
    /* 0x00E112DA-0x00E112F8 */
    network_$ps_send_reply(ps);
dump:
    network_$ppr_dump(ps);
    return;

getattr:
    /* 0x00E112FC-0x00E1131E */
    NETWORK_$INFO_RQST_CNT++;
    network_$ppr_dump(ps);
    rp->type = NETWORK_PS_RQST_GETATTR + 1;
    if ((NETWORK_$ALLOWED_SERVICE & NETWORK_PS_SERVICE_BIT) == 0 ||
        (ps->pkt_flags & NETWORK_PS_FLAG_REFUSE) != 0) {
        rp->hdr.status = status_$network_request_denied_by_remote_node;
        goto getattr_reply;                              /* 0x00E11466 */
    }

    {
        file_$obj_loc_t *loc = (file_$obj_loc_t *)(void *)&rp->bytes[8];
        uint16_t uid_bits;                               /* D1w */

        /* 0x00E11336-0x00E1138C: the location record */
        if (ps->rqst_copy_len == NETWORK_PS_RQST_MAX) {
            network_$ppr_copy(loc, &rq->bytes[0x12], 0x20);
        } else {
            loc->uid.high = rq->getattr.uid.high;
            loc->uid.low = rq->getattr.uid.low;
            loc->flags &= (int8_t)~FILE_OBJ_LOC_SCRATCH; /* bclr #6,(-0x1c3) */
        }
        rp->hdr.status = status_$ok;
        uid_bits = (uint16_t)((((uint16_t)(rq->getattr.uid.low >> 16) & 0xFF0) >> 4) &
                              0xE0);
        if (uid_bits != 0) {
            if (ps->rqst_copy_len == NETWORK_PS_RQST_MAX) {
                rp->hdr.status = status_$file_object_not_found;
            } else {
                loc->uid.low &= 0xF1FFFFFFu;             /* andi.b #-0xf,(-0x1d4) */
            }
        }

        /* 0x00E1138E-0x00E113C8 */
        if (rq->getattr.big < 0) {
            attr_flags = 0x281;
        } else {
            attr_flags = 0x81;
        }
        if (rp->hdr.status == status_$ok) {
            AST_$GET_ATTRIBUTES(loc, attr_flags, &rp->bytes[0x28],
                                (status_$t *)(void *)&rp->bytes[2]);
        }
        if (rp->hdr.status != status_$ok) {
            goto getattr_reply;
        }

        /* 0x00E113CC-0x00E11464 */
        uid_bits = (uint16_t)((((uint16_t)(rq->getattr.uid.low >> 16) & 0xFF0) >> 4) &
                              0xE0);
        if (uid_bits != 0) {
            if (rq->getattr.version < 5) {
                for (i = 0; i < 16; i++) {
                    rp->getattr.u.old.attrs.l[i] = 0;
                }
                rp->getattr.u.old.attrs.f.uid.high = rq->getattr.uid.high;
                rp->getattr.u.old.attrs.f.uid.low = rq->getattr.uid.low;
                rp->getattr.u.old.attrs.f.uid2.high = rq->getattr.uid.high;
                rp->getattr.u.old.attrs.f.uid2.low = rq->getattr.uid.low;
                rp->getattr.u.old.attrs.f.kind = 3;
                rp->getattr.u.old.attrs.f.size = 0x400;
            } else {
                rp->hdr.status = status_$file_object_not_found;
            }
        } else if (rq->getattr.version < 5) {
            old_flag = (rp->bytes[0x28] != 0) ? (int8_t)0xFF : 0;
            VTOCE_$NEW_TO_OLD(&rp->bytes[0x28], (char *)&old_flag, ps->old_attrs);
            for (i = 0; i < 16; i++) {
                rp->getattr.u.old.attrs.l[i] = ps->old_attrs[i];
            }
        }
    }

getattr_reply:
    /* 0x00E1146E-0x00E114A0 */
    ps->data_len = 0;
    ps->data_pages[0] = 0;
    if (rq->getattr.version < 5) {
        rp->getattr.u.old.version = NETWORK_PS_VERSION;
        ps->reply_len = 0x48;
    } else {
        rp->hdr.version = NETWORK_PS_VERSION;
        ps->reply_len = 0xB8;
    }
    ps->pkt_flags = 0x20;
    network_$ps_send_reply(ps);

    /* 0x00E114A4-0x00E114F6 */
    if (NETLOG_$OK_TO_LOG_SERVER >= 0) {
        return;
    }
    TIME_$ABS_CLOCK(&ps->end_clock);
    network_$ppr_log(ps, &netlog_word, 4, (uid_t *)(void *)&rq->bytes[2], 0, 0);
    return;

unknown:
    /* 0x00E114F8-0x00E11534 */
    network_$ppr_dump(ps);
    rp->type = NETWORK_PS_REPLY_UNKNOWN;
    rp->hdr.status = status_$network_unknown_request_type;
    rp->hdr.version = NETWORK_PS_VERSION;
    ps->data_len = 0;
    ps->data_pages[0] = 0;
    ps->pkt_flags = 0x20;
    ps->reply_len = 8;

send:
    /* 0x00E11538-0x00E1153E */
    network_$ps_send_reply(ps);
}
